/// The three drawables the intro slides and the About screen paint.
///
/// `res/drawable/intro_icon_1.png`, `intro_icon_2.png` and `intro_icon_4.png`
/// are what upstream shows: the Loop artwork on the About screen's first card
/// and on intro slide 1, the illustration of a habit card on slide 2, and the
/// illustration of a score graph on slide 3
/// (`audit3.the-loop-logo-and-the-two#1`). The port used to draw
/// approximations of all three with a `CustomPainter`.
///
/// They are carried here as base64 rather than as asset files because this
/// package declares no asset bundle: an image under `assets/` that pubspec.yaml
/// does not list is not shipped at all, and a widget asking for it would show
/// nothing on a device while passing every widget test. Bytes in the source
/// cannot go missing that way, and `Image.memory` needs nothing declared.
/// The originals are copied byte for byte, which is what
/// test/ui/intro/intro_artwork_test.dart checks against the Android source
/// set.
library;

